INSERT INTO public.book (created_at, updated_at, version, isbn, title, contents, url, publisher, thumbnail_url, published_at, author_id) VALUES ('2025-10-05 06:56:50.563931', '2025-10-05 06:56:50.563931', 1, '9788970128337', '달리기를 말할 때 내가 하고 싶은 이야기', '무라카미 하루키의 달리기를 축으로 한 문학과 인생의 회고록 『달리기를 말할 때 내가 하고 싶은 이야기』. 1979년 소설 〈바람의 노래를 들어라〉로 등단한 이래 연령과 국적을 불문하고, 폭넓은 사랑과 지지를 받으며 세계적인 작가로 자리매김한 ''무라카미 하루키''가 처음으로 펴낸 회고록이다. 달리는 소설가로 불리우는 하루키가 달리기를 축으로 인생과 문학에 대해 품고있던 생각을 허심탄회하게 털어놓았다.  무라카미 하루키에게 계속 달린다는 것은 어떤 의미로', 'https://search.daum.net/search?w=bookpage&bookId=954058&q=%EB%8B%AC%EB%A6%AC%EA%B8%B0%EB%A5%BC+%EB%A7%90%ED%95%A0+%EB%95%8C+%EB%82%B4%EA%B0%80+%ED%95%98%EA%B3%A0+%EC%8B%B6%EC%9D%80+%EC%9D%B4%EC%95%BC%EA%B8%B0', '문학사상', 'https://search1.kakaocdn.net/thumb/R120x174.q85/?fname=http%3A%2F%2Ft1.daumcdn.net%2Flbook%2Fimage%2F954058%3Ftimestamp%3D20250812110246', '2016-12-15 00:00:00', 1);
INSERT INTO public.book (created_at, updated_at, version, isbn, title, contents, url, publisher, thumbnail_url, published_at, author_id) VALUES ('2025-10-11 11:48:50.404308', '2025-10-11 11:48:50.404308', 1, '9788972757719', '직업으로서의 소설가', '무라카미 하루키는 ‘하루키스트’라는 조어가 생겨날 정도로 세계적으로 많은 독자를 가지고 있으면서도 한편으로는 많은 평론가들의 혹독한 평가를 받는다. ‘사회적으로 무책임’, ‘제국주의적’등 강도 높은 비난 속에서도 침묵으로 일관해왔던 그가 1979년 등단 이후 최초로 자신의 작가론적, 문단론적, 문예론적 견해를 풀어놓은 책 『직업으로서의 소설가』를 출간했다. 이따금 인터뷰나 에세이를 통해 언급했던 글쓰기와 그 현장을 비롯하여, 이를 뒷받침하는 문학을', 'https://search.daum.net/search?w=bookpage&bookId=1005605&q=%EC%A7%81%EC%97%85%EC%9C%BC%EB%A1%9C%EC%84%9C%EC%9D%98+%EC%86%8C%EC%84%A4%EA%B0%80', '현대문학', 'https://search1.kakaocdn.net/thumb/R120x174.q85/?fname=http%3A%2F%2Ft1.daumcdn.net%2Flbook%2Fimage%2F1005605%3Ftimestamp%3D20241207113515', '2016-04-25 00:00:00', 1);
INSERT INTO public.book (created_at, updated_at, version, isbn, title, contents, url, publisher, thumbnail_url, published_at, author_id) VALUES ('2025-10-11 11:49:22.493251', '2025-10-11 11:49:22.493251', 1, '9783540424697', 'Geoid, and Geodynamics 2000 : GGG2000 IAG International Symposium, Banf...', 'A veritable cornucopia of over 100 innovative materials, this book also offers architects and designers clever ideas on how to use them. Think of smart materials, for example, which react to changes in the immediate environment, and of materials that', 'https://search.daum.net/search?w=bookpage&bookId=2519131&q=Gravity%2C+Geoid%2C+and+Geodynamics+2000+%3A+GGG2000+IAG+International+Symposium%2C+Banf%2C+Alberta%2C+Canada%2C+J', 'Springer', 'https://search1.kakaocdn.net/thumb/R120x174.q85/?fname=http%3A%2F%2Ft1.daumcdn.net%2Flbook%2Fimage%2F2519131%3Ftimestamp%3D20230918164227', '2001-12-01 00:00:00', 34);
INSERT INTO public.book (created_at, updated_at, version, isbn, title, contents, url, publisher, thumbnail_url, published_at, author_id) VALUES ('2025-10-12 12:07:29.236442', '2025-10-12 12:07:29.236442', 1, '9788994343501', '무라카미 하루키 잡문집', '『무라카미 하루키 잡문집』은 1979년부터 2010년까지 써온 다양한 글 가운데 저자가 직접 엄선한 69편의 미발표 에세이, 미수록 단편소설 등을 엮은 책이다. 저자가 들려주는 진지한 문학론에서부터 번역가로서 저자가 들려주는 감각적인 번역론, 음악애호가로서 들려주는 깊이 있는 재즈론 그리고 인생론과 독서론까지 고스란히 담겨있다. 기존의 하루키 스타일을 오롯이 담아내면서도 새로운 하루키의 세계를 보여주는 이 책은 어느 정도 날것인 형태로 스스로를 표현하거나', 'https://search.daum.net/search?w=bookpage&bookId=1417299&q=%EB%AC%B4%EB%9D%BC%EC%B9%B4%EB%AF%B8+%ED%95%98%EB%A3%A8%ED%82%A4+%EC%9E%A1%EB%AC%B8%EC%A7%91', '비채', 'https://search1.kakaocdn.net/thumb/R120x174.q85/?fname=http%3A%2F%2Ft1.daumcdn.net%2Flbook%2Fimage%2F1417299%3Ftimestamp%3D20240206155243', '2011-11-22 00:00:00', 1);
INSERT INTO public.book (created_at, updated_at, version, isbn, title, contents, url, publisher, thumbnail_url, published_at, author_id) VALUES ('2025-10-12 12:28:26.620708', '2025-10-12 12:28:26.620708', 1, '6500611431001', 'the performance of adjustable speed drive (ASD) systems under power qualit', '', 'https://search.daum.net/search?w=bookpage&bookId=3991766&q=New+approaches+to+improve+the+performance+of+adjustable+speed+drive+%28ASD%29+systems+under+power+qualit', 'Endeavor Literary Press', '', '2021-01-01 00:00:00', 35);
INSERT INTO public.book (created_at, updated_at, version, isbn, title, contents, url, publisher, thumbnail_url, published_at, author_id) VALUES ('2025-10-12 12:32:30.508288', '2025-10-12 12:32:30.508288', 1, '9788984374942', '미로 속 아이', '마지막 한 줄을 다 읽고 나야 모든 의혹이 해소된다.  《미로 속 아이》 줄거리 요약  이탈리아의 저명한 기업가 카를로 디 피에트로의 상속녀이자 종군기자로 명성을 떨친 적이 있고, 출판사를 설립해 경영인으로도 뛰어난 수완을 보여준 오리아나 디 피에트로가 코트다쥐르 인근 레렝 제도 해상 위에 떠 있는 〈루나 블루호〉에 탑승했다가 괴한의 습격을 받고 혼수상태에 빠진다. 〈루나 블루호〉의 근처를 지나던 배에 탑승해 있던 여학생 두 명이 피투성이가 된', 'https://search.daum.net/search?w=bookpage&bookId=6795130&q=%EB%AF%B8%EB%A1%9C+%EC%86%8D+%EC%95%84%EC%9D%B4', '밝은세상', 'https://search1.kakaocdn.net/thumb/R120x174.q85/?fname=http%3A%2F%2Ft1.daumcdn.net%2Flbook%2Fimage%2F6795130%3Ftimestamp%3D20250101145901', '2024-12-17 00:00:00', 36);
INSERT INTO public.book (created_at, updated_at, version, isbn, title, contents, url, publisher, thumbnail_url, published_at, author_id) VALUES ('2025-10-12 12:52:39.944658', '2025-10-12 12:52:39.944658', 1, '9788961552707', '럭키 파트라슈(처음어린이 12)', '아이들의 꿈과 마음을 키우는 「처음어린이」 제12권 『럭키 파트라슈』. 2006년 조선일보 신춘문예에 동화가 당선되어 문단에 나온 동화작가 김진의, ''생명''에 대한 사랑과 배려를 깨닫게 해주는 따뜻한 감동 동화다. 한별네 에 입양된 강아지 ''럭키''의 이야기를 통해 동물도 인간과 다르지 않은 소중한 생명이라는 것을 일깨우면서 절대 학대하거나 무시해서는 안 된다는 것을 일깨워준다. 동물뿐 아니라, 다른 언어와 문화를 가진 외국인 노동자, 그리고 생활', 'https://search.daum.net/search?w=bookpage&bookId=851807&q=%EB%9F%AD%ED%82%A4+%ED%8C%8C%ED%8A%B8%EB%9D%BC%EC%8A%88%28%EC%B2%98%EC%9D%8C%EC%96%B4%EB%A6%B0%EC%9D%B4+12%29', '처음주니어', 'https://search1.kakaocdn.net/thumb/R120x174.q85/?fname=http%3A%2F%2Ft1.daumcdn.net%2Flbook%2Fimage%2F851807%3Ftimestamp%3D20221004005046', '2011-10-25 00:00:00', 37);
INSERT INTO public.book (created_at, updated_at, version, isbn, title, contents, url, publisher, thumbnail_url, published_at, author_id) VALUES ('2025-10-12 12:53:09.625412', '2025-10-12 12:53:09.625412', 1, '9781595081001', 'AAA Essential Venice', 'AAA Essential Venice is packed with full-color travel information, tips, maps and more. The innovative cover format includes an expansion flap on both front and back covers. Cover 2 and its facing page and cover 3 with its facing page depict frequently used', 'https://search.daum.net/search?w=bookpage&bookId=2112311&q=AAA+Essential+Venice', 'Simon & Schuster', 'https://search1.kakaocdn.net/thumb/R120x174.q85/?fname=http%3A%2F%2Ft1.daumcdn.net%2Flbook%2Fimage%2F2112311%3Ftimestamp%3D20230918183350', '2006-03-01 00:00:00', 38);
INSERT INTO public.book (created_at, updated_at, version, isbn, title, contents, url, publisher, thumbnail_url, published_at, author_id) VALUES ('2025-10-12 13:14:43.34298', '2025-10-12 13:14:43.34298', 1, '9788831000369', 'Matilde-La magica medicina-Il GGG-La fabbrica di cioccolato-Le streghe-Il', '', 'https://search.daum.net/search?w=bookpage&bookId=5457080&q=Roald+Dahl+da+collezione%3A+Matilde-La+magica+medicina-Il+GGG-La+fabbrica+di+cioccolato-Le+streghe-Il', 'Salani', '', '2020-09-24 00:00:00', 39);
INSERT INTO public.book (created_at, updated_at, version, isbn, title, contents, url, publisher, thumbnail_url, published_at, author_id) VALUES ('2025-10-25 04:50:43.634662', '2025-10-25 04:50:43.634662', 1, '9788954692663', '코끼리 공장의 해피엔드', '무라카미 하루키와 안자이 미즈마루 콤비의 첫 공동 작업물 『코끼리 공장의 해피엔드』와 『랑게르한스섬의 오후』를 함께 수록한 단행본. 재즈와 록, 팝 음악에서 영감을 받은 짤막한 글들과 센티멘털한 도시 일상의 에피소드가 안자이 미즈마루의 컬러풀한 일러스트와 함께 아름다운 하모니를 이룬다.', 'https://search.daum.net/search?w=bookpage&bookId=6351938&q=%EC%BD%94%EB%81%BC%EB%A6%AC+%EA%B3%B5%EC%9E%A5%EC%9D%98+%ED%95%B4%ED%94%BC%EC%97%94%EB%93%9C', '문학동네', 'https://search1.kakaocdn.net/thumb/R120x174.q85/?fname=http%3A%2F%2Ft1.daumcdn.net%2Flbook%2Fimage%2F6351938%3Ftimestamp%3D20241211154216', '2023-05-18 00:00:00', 1);
INSERT INTO public.book (created_at, updated_at, version, isbn, title, contents, url, publisher, thumbnail_url, published_at, author_id) VALUES ('2025-10-12 13:15:23.556549', '2025-10-12 13:15:23.556549', 1, '8809255052886', '콕콕콕 사운드 벽보: 123 + 가나다 세트(전2권)', '1. 손으로 콕콕콕! - 도구 없이 손으로 콕 누르면 내장된 스피커에서 소리가 나와요. - 어느 곳을 눌러도 소리가 나와 아이가 쉽게 할 수 있어요.  2. 한글, 영어가 콕콕콕! - 123의 〈우리말〉 모드는 숫자와 개수, 가나다의 〈우리말〉 모드는 한글의 음절과 사물의 이름을 /〈Eng〉 모드는 영어 이름을(가나다 제외) 들려줘요. - 한글과 영어를 듣고 말하며, 언어 발달을 자극해요.  3. 재밌는 퀴즈도 콕콕콕! -한글 퀴즈와 영어 퀴즈가', 'https://search.daum.net/search?w=bookpage&bookId=5624832&q=%EC%BD%95%EC%BD%95%EC%BD%95+%EC%82%AC%EC%9A%B4%EB%93%9C+%EB%B2%BD%EB%B3%B4%3A+123+%2B+%EA%B0%80%EB%82%98%EB%8B%A4+%EC%84%B8%ED%8A%B8%28%EC%A0%842%EA%B6%8C%29', '키움터', 'https://search1.kakaocdn.net/thumb/R120x174.q85/?fname=http%3A%2F%2Ft1.daumcdn.net%2Flbook%2Fimage%2F5624832%3Ftimestamp%3D20220807192337', '2021-01-29 00:00:00', 40);
INSERT INTO public.book (created_at, updated_at, version, isbn, title, contents, url, publisher, thumbnail_url, published_at, author_id) VALUES ('2025-10-25 01:17:46.021272', '2025-10-25 01:17:46.021272', 1, '9788954625586', '여자 없는 남자들', '『여자 없는 남자들』은 무라카미 하루키가 《도쿄 기담집》 이후 9년 만에 펴낸 단편집으로 일본 출간 당시 예약판매로만 30만 부의 판매고를 올린 화제의 책이다. 그간 장편소설 집필에 몰두해왔던 저자가 2013년 말부터 이듬해 봄에 걸쳐 발표한 다섯 편의 단편과 단행본 출간에 맞춰 새로 쓴 표제작 ‘여자 없는 남자들’, 저자가 직접 선별한 영미권 단편소설 모음집 《그리워서》에 수록된 ‘사랑하는 잠자’까지 만나볼 수 있다.  병으로 인해 사별한 가', 'https://search.daum.net/search?w=bookpage&bookId=691680&q=%EC%97%AC%EC%9E%90+%EC%97%86%EB%8A%94+%EB%82%A8%EC%9E%90%EB%93%A4', '문학동네', 'https://search1.kakaocdn.net/thumb/R120x174.q85/?fname=http%3A%2F%2Ft1.daumcdn.net%2Flbook%2Fimage%2F691680%3Ftimestamp%3D20250422114206', '2014-08-28 00:00:00', 1);
INSERT INTO public.book (created_at, updated_at, version, isbn, title, contents, url, publisher, thumbnail_url, published_at, author_id) VALUES ('2025-10-25 01:17:57.966623', '2025-10-25 01:17:57.966623', 1, '9788954672047', '무라카미 하루키 에세이 걸작선 세트', '『노르웨이의 숲』 『해변의 카프카』 등으로 폭넓은 사랑과 지지를 받아오며 2009년 『1Q84』로 다시 한번 국내에 열풍을 일으킨 무라카미 하루키. 그의 본업은 당연히 소설가지만 오래전부터 꾸준히 그의 작품을 읽어온 독자라면 안자이 미즈마루의 심플하고도 재치 넘치는 삽화가 들어간 수필집 시리즈를 기억할 것이다. 하루키 팬들이 가장 사랑하는 시리즈로 꼽은 이 에세이가 국내 정식 출간 계약을 거쳐 새로운 모습으로 선보인다. 소설에서 엿보이는 것과는', 'https://search.daum.net/search?w=bookpage&bookId=5388519&q=%EB%AC%B4%EB%9D%BC%EC%B9%B4%EB%AF%B8+%ED%95%98%EB%A3%A8%ED%82%A4+%EC%97%90%EC%84%B8%EC%9D%B4+%EA%B1%B8%EC%9E%91%EC%84%A0+%EC%84%B8%ED%8A%B8', '문학동네', 'https://search1.kakaocdn.net/thumb/R120x174.q85/?fname=http%3A%2F%2Ft1.daumcdn.net%2Flbook%2Fimage%2F5388519%3Ftimestamp%3D20230516175523', '2020-06-03 00:00:00', 1);
INSERT INTO public.book (created_at, updated_at, version, isbn, title, contents, url, publisher, thumbnail_url, published_at, author_id) VALUES ('2025-10-25 01:18:19.370786', '2025-10-25 01:18:19.370786', 1, '9791130616650', '베어타운', '《오베라는 남자》로 전 세계를 사로잡은 프레드릭 배크만이 모두의 가슴을 울리는 새로운 이야기 『베어타운』. 일자리도, 미래도 없이 막다른 곳에 내몰린 소도시, 베어타운을 배경으로 공동체를 하나로 엮는 희망과 그 공동체를 갈기갈기 찢어놓는 비밀, 대의를 위해 잡음을 모른척하려는 이기심과 대의에 반하는 선택을 하는 한 개인의 용기를 생생하게 그려낸 작품이다.  온 마을이 아이스하키에 매달리는 베어타운은 과거의 영광도 하키로 이루었고, 몰락도 하키에서', 'https://search.daum.net/search?w=bookpage&bookId=1536333&q=%EB%B2%A0%EC%96%B4%ED%83%80%EC%9A%B4', '다산책방', 'https://search1.kakaocdn.net/thumb/R120x174.q85/?fname=http%3A%2F%2Ft1.daumcdn.net%2Flbook%2Fimage%2F1536333%3Ftimestamp%3D20251002111318', '2018-04-18 00:00:00', 41);
INSERT INTO public.book (created_at, updated_at, version, isbn, title, contents, url, publisher, thumbnail_url, published_at, author_id) VALUES ('2025-10-25 01:18:41.20745', '2025-10-25 01:18:41.20745', 1, '9791130637617', '불안한 사람들', '『오베라는 남자』로 전 세계를 사로잡은 감동소설의 대가 프레드릭 배크만이 웃음도 감동도 한층 짙어진 새로운 장편소설 『불안한 사람들』로 돌아왔다. 이 작품은 “역시 배크만은 틀릴 리가 없다” “팬데믹 시대의 불안을 해소해줄 가장 믿음직한 치료제” “공포 속 희망, 비극 속 유머, 혼돈 속 우아함, 웃음 속 눈물이 황홀하게 쏟아져 내린다” 등 열광적인 찬사를 받으며 다시 한번 배크만만이 도달 가능한 독보적인 영역을 증명했다. 또한 출간 즉시 아마존', 'https://search.daum.net/search?w=bookpage&bookId=5689621&q=%EB%B6%88%EC%95%88%ED%95%9C+%EC%82%AC%EB%9E%8C%EB%93%A4', '다산책방', 'https://search1.kakaocdn.net/thumb/R120x174.q85/?fname=http%3A%2F%2Ft1.daumcdn.net%2Flbook%2Fimage%2F5689621%3Ftimestamp%3D20251002135514', '2021-05-14 00:00:00', 41);
INSERT INTO public.book (created_at, updated_at, version, isbn, title, contents, url, publisher, thumbnail_url, published_at, author_id) VALUES ('2025-10-25 01:18:59.893998', '2025-10-25 01:18:59.893998', 1, '9791130649177', '위너 1', '★ 1300만 독자가 사랑한 『오베라는 남자』 작가의 신작 ★ ★ 2022년 굿리즈 최고의 소설 최종 후보작 ★ ★ 아마존 소설 부문 에디터스 픽 ★ ★ 애플북스 베스트셀러 ★ ★ 시리즈 누적 판매 175만 부 이상 ★ ★ 『미 비포 유』 작가 조조 모예스 강력 추천 ★  『오베라는 남자』로 전 세계에 이름을 각인시키고, 『불안한 사람들』로 독자를 웃기고 울린 프레드릭 배크만이 2년 만에 『위너』로 돌아왔다. 이 소설은 스웨덴 현지를 비롯해 해외', 'https://search.daum.net/search?w=bookpage&bookId=6503840&q=%EC%9C%84%EB%84%88+1', '다산책방', 'https://search1.kakaocdn.net/thumb/R120x174.q85/?fname=http%3A%2F%2Ft1.daumcdn.net%2Flbook%2Fimage%2F6503840%3Ftimestamp%3D20251017143307', '2023-12-04 00:00:00', 41);
INSERT INTO public.book (created_at, updated_at, version, isbn, title, contents, url, publisher, thumbnail_url, published_at, author_id) VALUES ('2025-10-25 01:19:13.84337', '2025-10-25 01:19:13.84337', 1, '9791130649184', '위너 2', '★ 1300만 독자가 사랑한 『오베라는 남자』 작가의 신작 ★ ★ 2022년 굿리즈 최고의 소설 최종 후보작 ★ ★ 아마존 소설 부문 에디터스 픽 ★ ★ 애플북스 베스트셀러 ★ ★ 시리즈 누적 판매 175만 부 이상 ★ ★ 『미 비포 유』 작가 조조 모예스 강력 추천 ★  『오베라는 남자』로 전 세계에 이름을 각인시키고, 『불안한 사람들』로 독자를 웃기고 울린 프레드릭 배크만이 2년 만에 『위너』로 돌아왔다. 이 소설은 스웨덴 현지를 비롯해 해외', 'https://search.daum.net/search?w=bookpage&bookId=6503647&q=%EC%9C%84%EB%84%88+2', '다산책방', 'https://search1.kakaocdn.net/thumb/R120x174.q85/?fname=http%3A%2F%2Ft1.daumcdn.net%2Flbook%2Fimage%2F6503647%3Ftimestamp%3D20251015143126', '2023-12-04 00:00:00', 41);
INSERT INTO public.book (created_at, updated_at, version, isbn, title, contents, url, publisher, thumbnail_url, published_at, author_id) VALUES ('2025-10-25 01:19:32.52852', '2025-10-25 01:19:32.52852', 1, '9788970125466', '해변의 카프카 1', '“너는 지금부터 이 세상에서 가장 터프한 열다섯 살 소년이 된다.” “그리고 눈을 떴을 때, 너는 새로운 세계의 일부가 되어 있다.”  하루키 스타일의 묘미를 오롯이 살린 16년 만의 전면 개정판! 인간 삶의 원형을 탐구하는 정신분석학적 매직 리얼리즘', 'https://search.daum.net/search?w=bookpage&bookId=6639751&q=%ED%95%B4%EB%B3%80%EC%9D%98+%EC%B9%B4%ED%94%84%EC%B9%B4+1', '문학사상', 'https://search1.kakaocdn.net/thumb/R120x174.q85/?fname=http%3A%2F%2Ft1.daumcdn.net%2Flbook%2Fimage%2F6639751%3Ftimestamp%3D20250627150238', '2024-06-10 00:00:00', 1);
INSERT INTO public.book (created_at, updated_at, version, isbn, title, contents, url, publisher, thumbnail_url, published_at, author_id) VALUES ('2025-10-25 01:19:50.003188', '2025-10-25 01:19:50.003188', 1, '9788970124988', '해변의 카프카(상)', '', 'https://search.daum.net/search?w=bookpage&bookId=954385&q=%ED%95%B4%EB%B3%80%EC%9D%98+%EC%B9%B4%ED%94%84%EC%B9%B4%28%EC%83%81%29', '문학사상사', 'https://search1.kakaocdn.net/thumb/R120x174.q85/?fname=http%3A%2F%2Ft1.daumcdn.net%2Flbook%2Fimage%2F954385%3Ftimestamp%3D20221011185431', '2003-07-25 00:00:00', 1);
INSERT INTO public.book (created_at, updated_at, version, isbn, title, contents, url, publisher, thumbnail_url, published_at, author_id) VALUES ('2025-10-25 01:20:06.573232', '2025-10-25 01:20:06.573232', 1, '9788970128092', '해변의 카프카(하)', '무라카미 하루키 장편소설『해변의 카프카』하권. 하루키의 23년 문학 인생을 집대성한 작품으로, 인간의 근원적 명제인 삶의 의미와 가치에 대해 이야기한다. 아이들의 꿈과 어른들이 만들어낸 현실의 틈에 자리한 미궁 속에서 끝없이 방황하고 고뇌하며 힘겹게 성장해 가는 열다섯 살 소년의 모습을 통해 산다는 것의 의미를 확인하고 있다.  이 소설은 오이디푸스의 비극을 예언한 아버지의 저주에서 벗어나기 위해 집을 나온 열다섯 살 소년과, 어린 시절의 기묘', 'https://search.daum.net/search?w=bookpage&bookId=954647&q=%ED%95%B4%EB%B3%80%EC%9D%98+%EC%B9%B4%ED%94%84%EC%B9%B4%28%ED%95%98%29', '문학사상사', 'https://search1.kakaocdn.net/thumb/R120x174.q85/?fname=http%3A%2F%2Ft1.daumcdn.net%2Flbook%2Fimage%2F954647%3Ftimestamp%3D20240530113029', '2008-05-16 00:00:00', 1);
INSERT INTO public.book (created_at, updated_at, version, isbn, title, contents, url, publisher, thumbnail_url, published_at, author_id) VALUES ('2025-10-25 01:20:51.987841', '2025-10-25 01:20:51.987841', 1, '9788954646123', '기사단장 죽이기 1: 현현하는 이데아', '무라카미 하루키가 7년 만에 선보인 본격 장편소설 『기사단장 죽이기』제1권. ‘이것이 하루키다!’라고 말할 수 있는 요소가 전부 담겨 있다는 평을 들으며 일본 출간 당시 130만 부 제작 발행으로 화제가 되었던 작품이다. 저자가 지금까지 구축해온 작품세계를 다양하게 변주하며 현세대 독자에게 던지는 메시지이자 한 사람의 예술가로서 내면 깊은 곳까지 내려가 농축한 결과물이다.  저자가 작가생활 초기에 주로 썼던 일인칭 시점으로 돌아와 그 매력이 한층', 'https://search.daum.net/search?w=bookpage&bookId=694091&q=%EA%B8%B0%EC%82%AC%EB%8B%A8%EC%9E%A5+%EC%A3%BD%EC%9D%B4%EA%B8%B0+1%3A+%ED%98%84%ED%98%84%ED%95%98%EB%8A%94+%EC%9D%B4%EB%8D%B0%EC%95%84', '문학동네', 'https://search1.kakaocdn.net/thumb/R120x174.q85/?fname=http%3A%2F%2Ft1.daumcdn.net%2Flbook%2Fimage%2F694091%3Ftimestamp%3D20250226113407', '2017-07-12 00:00:00', 1);
INSERT INTO public.book (created_at, updated_at, version, isbn, title, contents, url, publisher, thumbnail_url, published_at, author_id) VALUES ('2025-10-25 01:21:06.352235', '2025-10-25 01:21:06.352235', 1, '9788954646130', '기사단장 죽이기 2: 전이하는 메타포', '무라카미 하루키가 7년 만에 선보인 본격 장편소설 『기사단장 죽이기』제2권. ‘이것이 하루키다!’라고 말할 수 있는 요소가 전부 담겨 있다는 평을 들으며 일본 출간 당시 130만 부 제작 발행으로 화제가 되었던 작품이다. 저자가 지금까지 구축해온 작품세계를 다양하게 변주하며 현세대 독자에게 던지는 메시지이자 한 사람의 예술가로서 내면 깊은 곳까지 내려가 농축한 결과물이다.  저자가 작가생활 초기에 주로 썼던 일인칭 시점으로 돌아와 그 매력이 한층', 'https://search.daum.net/search?w=bookpage&bookId=693084&q=%EA%B8%B0%EC%82%AC%EB%8B%A8%EC%9E%A5+%EC%A3%BD%EC%9D%B4%EA%B8%B0+2%3A+%EC%A0%84%EC%9D%B4%ED%95%98%EB%8A%94+%EB%A9%94%ED%83%80%ED%8F%AC', '문학동네', 'https://search1.kakaocdn.net/thumb/R120x174.q85/?fname=http%3A%2F%2Ft1.daumcdn.net%2Flbook%2Fimage%2F693084%3Ftimestamp%3D20250521180911', '2017-07-12 00:00:00', 1);
INSERT INTO public.book (created_at, updated_at, version, isbn, title, contents, url, publisher, thumbnail_url, published_at, author_id) VALUES ('2025-10-25 01:21:27.880302', '2025-10-25 01:21:27.880302', 1, '9788954608640', '1Q84 1', '무라카미 하루키가 〈어둠의 저편〉 이후 5년 만에 펴낸 장편소설『1Q84』제1권. 해마다 노벨상 후보에 거론되며, 일본은 물론 세계적으로 많은 사랑을 받고 있는 작가 무라카미 하루키. 그가 이번에는 두 남녀의 아련한 첫사랑 이야기인 동시에 ''1Q84''를 헤쳐나가며 겪게 되는 환상적인 이야기를 그렸다. 압도적인 이야기의 강렬함과 흡인력이 돋보인다.  스타일리시한 여자 암살자 아오마메와 작가지망생 덴고. 꽉 막힌 고속도로의 비상계단을 내려오면서 다른 세계', 'https://search.daum.net/search?w=bookpage&bookId=690267&q=1Q84+1', '문학동네', 'https://search1.kakaocdn.net/thumb/R120x174.q85/?fname=http%3A%2F%2Ft1.daumcdn.net%2Flbook%2Fimage%2F690267%3Ftimestamp%3D20241107114154', '2009-08-25 00:00:00', 1);
INSERT INTO public.book (created_at, updated_at, version, isbn, title, contents, url, publisher, thumbnail_url, published_at, author_id) VALUES ('2025-10-25 01:21:38.476953', '2025-10-25 01:21:38.476953', 1, '9788954608657', '1Q84 2', '무라카미 하루키가 &lt;어둠의 저편&gt; 이후 5년 만에 펴낸 장편소설『1Q84』제2권. 해마다 노벨상 후보에 거론되며, 일본은 물론 세계적으로 많은 사랑을 받고 있는 작가 무라카미 하루키. 그가 이번에는 두 남녀의 아련한 첫사랑 이야기인 동시에 ''1Q84''를 헤쳐나가며 겪게 되는 환상적인 이야기를 그렸다. 압도적인 이야기의 강렬함과 흡인력이 돋보인다.    스타일리시한 여자 암살자 아오마메와 작가지망생 덴고. 꽉 막힌 고속도로의 비상계단을 내려오면서', 'https://search.daum.net/search?w=bookpage&bookId=690448&q=1Q84+2', '문학동네', 'https://search1.kakaocdn.net/thumb/R120x174.q85/?fname=http%3A%2F%2Ft1.daumcdn.net%2Flbook%2Fimage%2F690448%3Ftimestamp%3D20250628112905', '2009-09-08 00:00:00', 1);
INSERT INTO public.book (created_at, updated_at, version, isbn, title, contents, url, publisher, thumbnail_url, published_at, author_id) VALUES ('2025-10-25 01:22:29.705255', '2025-10-25 01:22:29.705255', 1, '9788954611800', '1Q84 3', '무라카미 하루키가 &lt;어둠의 저편&gt; 이후 5년 만에 펴낸 장편소설『1Q84』제3권. 해마다 노벨상 후보에 거론되며, 일본은 물론 세계적으로 많은 사랑을 받고 있는 작가 무라카미 하루키. 그가 이번에는 두 남녀의 아련한 첫사랑 이야기인 동시에 ''1Q84''를 헤쳐나가며 겪게 되는 환상적인 이야기를 그렸다. 압도적인 이야기의 강렬함과 흡인력이 돋보인다. 스타일리시한 여자 암살자 아오마메와 작가지망생 덴고. 꽉 막힌 고속도로의 비상계단을 내려오면서 다른', 'https://search.daum.net/search?w=bookpage&bookId=690663&q=1Q84+3', '문학동네', 'https://search1.kakaocdn.net/thumb/R120x174.q85/?fname=http%3A%2F%2Ft1.daumcdn.net%2Flbook%2Fimage%2F690663%3Ftimestamp%3D20250828110319', '2010-07-27 00:00:00', 1);
INSERT INTO public.book (created_at, updated_at, version, isbn, title, contents, url, publisher, thumbnail_url, published_at, author_id) VALUES ('2025-10-25 01:24:12.834777', '2025-10-25 01:24:12.834777', 1, '9788970125930', '이렇게 작지만 확실한 행복', '‘소확행’ 열풍을 불러일으킨 무라카미 하루키 감성 에세이', 'https://search.daum.net/search?w=bookpage&bookId=6655174&q=%EC%9D%B4%EB%A0%87%EA%B2%8C+%EC%9E%91%EC%A7%80%EB%A7%8C+%ED%99%95%EC%8B%A4%ED%95%9C+%ED%96%89%EB%B3%B5', '문학사상', 'https://search1.kakaocdn.net/thumb/R120x174.q85/?fname=http%3A%2F%2Ft1.daumcdn.net%2Flbook%2Fimage%2F6655174%3Ftimestamp%3D20250708143517', '2024-06-10 00:00:00', 1);
INSERT INTO public.book (created_at, updated_at, version, isbn, title, contents, url, publisher, thumbnail_url, published_at, author_id) VALUES ('2025-10-25 04:46:23.04719', '2025-10-25 04:46:23.04719', 1, '9791130610375', '브릿마리 여기 있다', '《오베라는 남자》의 저자 프레드릭 배크만의 신작 장편소설 『브릿마리 여기 있다』. 타고난 결벽증에 까다롭기 그지없고, 늘 과하게 솔직해 이웃에게도, 남편에게도 수동 공격적이며 사회성이 부족하다는 오해를 사는 브릿마리. 그런 탓에 늘 누군가의 그늘로만 살아오던 브릿마리가 삶의 위기를 겪고 난 뒤 태어나서 처음으로 온전히 나만의 삶을 찾아 떠나는 가슴 뭉클한 여정을 담은 작품이다.    엉망진창인 싱크대 서랍을 용서할 수 없는 죄로 여기며, 정신병자', 'https://search.daum.net/search?w=bookpage&bookId=1538969&q=%EB%B8%8C%EB%A6%BF%EB%A7%88%EB%A6%AC+%EC%97%AC%EA%B8%B0+%EC%9E%88%EB%8B%A4', '다산책방', 'https://search1.kakaocdn.net/thumb/R120x174.q85/?fname=http%3A%2F%2Ft1.daumcdn.net%2Flbook%2Fimage%2F1538969%3Ftimestamp%3D20251001110409', '2016-12-06 00:00:00', 41);
INSERT INTO public.book (created_at, updated_at, version, isbn, title, contents, url, publisher, thumbnail_url, published_at, author_id) VALUES ('2025-10-25 04:51:31.644257', '2025-10-25 04:51:31.644257', 1, '9788954692670', '밸런타인데이의 무말랭이', '〈일간 아르바이트 뉴스〉에 연재한 90여 편의 에세이를 모은 작품집. ‘시티 워킹’이란 주제로, 학생 시절부터 작가가 된 지금까지 하루키가 겪어온 도쿄와 근교 생활에 대한 단상들을 담았다. 글의 내용을 재치 있게 살려낸 안자이 미즈마루의 삽화와 부록으로 실린 두 사람의 대담도 빼놓을 수 없는 볼거리.', 'https://search.daum.net/search?w=bookpage&bookId=6352008&q=%EB%B0%B8%EB%9F%B0%ED%83%80%EC%9D%B8%EB%8D%B0%EC%9D%B4%EC%9D%98+%EB%AC%B4%EB%A7%90%EB%9E%AD%EC%9D%B4', '문학동네', 'https://search1.kakaocdn.net/thumb/R120x174.q85/?fname=http%3A%2F%2Ft1.daumcdn.net%2Flbook%2Fimage%2F6352008%3Ftimestamp%3D20250108152845', '2023-05-18 00:00:00', 1);
INSERT INTO public.book (created_at, updated_at, version, isbn, title, contents, url, publisher, thumbnail_url, published_at, author_id) VALUES ('2025-10-25 04:51:49.904903', '2025-10-25 04:51:49.904903', 1, '9791170281283', '무라카미 하루키는 어렵다', '2017년 2월 일본 서점가에 하루키 바람이 다시 분다. 무라카미 하루키가 《1Q84》 이후 무려 7년에 본격 장편 《기사단장 죽이기》를 출시했기 때문이다. 출간 시 제작 부수만, 총 130만부를 찍은 이번 신작은 하루키 브랜드가 폭발력을 갖고 귀환했음을 시사한다. 하루키 앞에 불황은 없다.    그러나 『무라카미 하루키는 어렵다』의 저자는 하루키를 다른 관점에서 바라본다. 오히려 해외에서 큰 인기를 거머쥠과 동시에, 일본 국내에서 그의 문학을', 'https://search.daum.net/search?w=bookpage&bookId=1611753&q=%EB%AC%B4%EB%9D%BC%EC%B9%B4%EB%AF%B8+%ED%95%98%EB%A3%A8%ED%82%A4%EB%8A%94+%EC%96%B4%EB%A0%B5%EB%8B%A4', '책담', 'https://search1.kakaocdn.net/thumb/R120x174.q85/?fname=http%3A%2F%2Ft1.daumcdn.net%2Flbook%2Fimage%2F1611753%3Ftimestamp%3D20240904113840', '2017-03-20 00:00:00', 42);
INSERT INTO public.book (created_at, updated_at, version, isbn, title, contents, url, publisher, thumbnail_url, published_at, author_id) VALUES ('2025-10-25 05:01:08.615128', '2025-10-25 05:01:08.615128', 1, '9791169792974', '슬램덩크 챔프', '『슬램덩크 챔프』는 처음 접하는 독자를 위해 원작 만화 전 278화 에서 이야기의 베이스가 되는 24화를 엄선하여 수록하였다. 이 책 한권으로 북산 농구부의 결성과 기적의 진화를 들여다 볼 수 있다. 스포츠 만화의 황금기를 고스란히 담고 있는 슬램덩크의 명장면, 명대사가 고스란히 담겨 있어 영화를 관람하고 한번 더 원작의 향수에 젖고 싶은 팬들에게 소중한 선물이 될 것이다.', 'https://search.daum.net/search?w=bookpage&bookId=6253805&q=%EC%8A%AC%EB%9E%A8%EB%8D%A9%ED%81%AC+%EC%B1%94%ED%94%84', '대원씨아이', 'https://search1.kakaocdn.net/thumb/R120x174.q85/?fname=http%3A%2F%2Ft1.daumcdn.net%2Flbook%2Fimage%2F6253805%3Ftimestamp%3D20250826142244', '2023-01-31 00:00:00', 43);
INSERT INTO public.book (created_at, updated_at, version, isbn, title, contents, url, publisher, thumbnail_url, published_at, author_id) VALUES ('2025-10-25 06:11:58.800776', '2025-10-25 06:11:58.800776', 1, '9791128390920', '키드갱. 25', '신영우의 만화 『키드갱』 제25권. 태산파를 이끌고 들이닥친 황상무와 대면하게 된 대봉. 대봉은 황상무와 협상으로 평화롭게 해결하려 하지만 악행에는 대가가 뒤따르는 법. 지금부터 대봉의 정의가 실현된다!', 'https://search.daum.net/search?w=bookpage&bookId=1530736&q=%ED%82%A4%EB%93%9C%EA%B0%B1.+25', '삼양출판사', 'https://search1.kakaocdn.net/thumb/R120x174.q85/?fname=http%3A%2F%2Ft1.daumcdn.net%2Flbook%2Fimage%2F1530736%3Ftimestamp%3D20190130163706', '2017-02-20 00:00:00', 44);
